CREATE TABLE IF NOT EXISTS "categoria" (
	"id_categoria" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nombre" VARCHAR(60) NOT NULL UNIQUE,
	PRIMARY KEY("id_categoria")
);

CREATE TABLE IF NOT EXISTS "rol" (
	"id_rol" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	-- administrador, maestro
	"nombre" VARCHAR(30) NOT NULL UNIQUE,
	PRIMARY KEY("id_rol")
);

COMMENT ON COLUMN "rol"."nombre" IS 'administrador, maestro';

CREATE TABLE IF NOT EXISTS "usuario" (
	"id_usuario" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_rol" INTEGER NOT NULL,
	"nombre" VARCHAR(80) NOT NULL,
	"apellido_paterno" VARCHAR(100) NOT NULL,
	"apellido_materno" VARCHAR(100),
	"correo" VARCHAR(120) NOT NULL UNIQUE,
	"password_hash" VARCHAR(255) NOT NULL,
	"activo" BOOLEAN NOT NULL DEFAULT true,
	"fecha_creacion" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id_usuario")
);

CREATE TABLE IF NOT EXISTS "grado" (
	"id_grado" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"nombre" VARCHAR(20) NOT NULL UNIQUE,
	PRIMARY KEY("id_grado")
);

CREATE TABLE IF NOT EXISTS "grupo" (
	"id_grupo" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_grado" INTEGER NOT NULL,
	"nombre" VARCHAR(10) NOT NULL,
	"ciclo_escolar" VARCHAR(9) NOT NULL,
	PRIMARY KEY("id_grupo")
);

CREATE UNIQUE INDEX ""
ON "grupo" ("id_grado", "nombre", "ciclo_escolar");

CREATE TABLE IF NOT EXISTS "maestro_grupo" (
	"id_maestro_grupo" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_usuario" INTEGER NOT NULL,
	"id_grupo" INTEGER NOT NULL,
	PRIMARY KEY("id_maestro_grupo")
);

CREATE UNIQUE INDEX ""
ON "maestro_grupo" ("id_usuario", "id_grupo");

CREATE TABLE IF NOT EXISTS "libro" (
	"id_libro" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_categoria" INTEGER,
	"titulo" VARCHAR(150) NOT NULL,
	"autor" VARCHAR(120),
	"descripcion" TEXT,
	"portada_url" VARCHAR(255),
	"archivo_url" VARCHAR(255) NOT NULL,
	"id_usuario" INTEGER NOT NULL,
	"fecha_creacion" TIMESTAMP NOT NULL DEFAULT now(),
	-- borrado lógico
	"fecha_eliminacion" TIMESTAMP,
	PRIMARY KEY("id_libro")
);

COMMENT ON COLUMN "libro"."fecha_eliminacion" IS 'borrado lógico';

CREATE TABLE IF NOT EXISTS "libro_grado" (
	"id_libro_grado" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_libro" INTEGER NOT NULL,
	"id_grado" INTEGER NOT NULL,
	PRIMARY KEY("id_libro_grado")
);

CREATE UNIQUE INDEX ""
ON "libro_grado" ("id_libro", "id_grado");

CREATE TABLE IF NOT EXISTS "actividad" (
	"id_actividad" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_libro" INTEGER NOT NULL,
	"titulo" VARCHAR(150) NOT NULL,
	"instrucciones" TEXT NOT NULL,
	"id_usuario_creador" INTEGER NOT NULL,
	"fecha_creacion" TIMESTAMP NOT NULL DEFAULT now(),
	-- borrado lógico
	"fecha_eliminacion" TIMESTAMP,
	PRIMARY KEY("id_actividad")
);

COMMENT ON COLUMN "actividad"."fecha_eliminacion" IS 'borrado lógico';

CREATE TABLE IF NOT EXISTS "pregunta" (
	"id_pregunta" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_actividad" INTEGER NOT NULL,
	"enunciado" TEXT NOT NULL,
	-- opcion_multiple, verdadero_falso, abierta
	"tipo" VARCHAR(20) NOT NULL,
	"orden" SMALLINT NOT NULL,
	PRIMARY KEY("id_pregunta")
);

COMMENT ON COLUMN "pregunta"."tipo" IS 'opcion_multiple, verdadero_falso, abierta';

CREATE UNIQUE INDEX ""
ON "pregunta" ("id_actividad", "orden");

CREATE TABLE IF NOT EXISTS "opcion" (
	"id_opcion" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_pregunta" INTEGER NOT NULL,
	"texto" VARCHAR(255) NOT NULL,
	"es_correcta" BOOLEAN NOT NULL DEFAULT false,
	"orden" SMALLINT NOT NULL,
	PRIMARY KEY("id_opcion")
);

CREATE TABLE IF NOT EXISTS "bitacora" (
	"id_bitacora" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_usuario" INTEGER NOT NULL,
	-- crear, editar, eliminar
	"accion" VARCHAR(20) NOT NULL,
	-- libro, actividad
	"entidad" VARCHAR(30) NOT NULL,
	-- sin FK, apunta según entidad
	"id_entidad" INTEGER NOT NULL,
	"detalle" JSONB,
	"fecha" TIMESTAMP NOT NULL DEFAULT now(),
	PRIMARY KEY("id_bitacora")
);

COMMENT ON COLUMN "bitacora"."accion" IS 'crear, editar, eliminar';
COMMENT ON COLUMN "bitacora"."entidad" IS 'libro, actividad';
COMMENT ON COLUMN "bitacora"."id_entidad" IS 'sin FK, apunta según entidad';

CREATE TABLE IF NOT EXISTS "aplicacion_actividad" (
	"id_aplicacion" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"id_sesion" INTEGER NOT NULL,
	"id_actividad" INTEGER NOT NULL,
	"fecha_mostrada" TIMESTAMP NOT NULL DEFAULT now(),
	"fecha_fin" TIMESTAMP,
	PRIMARY KEY("id_aplicacion")
);

CREATE TABLE IF NOT EXISTS "sesion_lectura" (
	"id_sesion" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	-- maestro que proyecta
	"id_usuario" INTEGER NOT NULL,
	"id_libro" INTEGER NOT NULL,
	"id_grupo" INTEGER NOT NULL,
	"fecha_inicio" TIMESTAMP NOT NULL DEFAULT now(),
	"fecha_fin" TIMESTAMP,
	"observaciones" TEXT,
	PRIMARY KEY("id_sesion")
);

COMMENT ON COLUMN "sesion_lectura"."id_usuario" IS 'maestro que proyecta';

CREATE INDEX ""
ON "sesion_lectura" ("id_usuario", "fecha_inicio");
CREATE INDEX ""
ON "sesion_lectura" ("id_libro");

